import{_ as o,a0 as l,w as d,s as r,I as i,x as s,a1 as a,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Linux 中切换相同程序的不同版本 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中切换相同程序的不同版本 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中切换相同程序的不同版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中切换相同程序的不同版本 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180813 How To Switch Between Different Versions Of Commands In Linux","title":"如何在 Linux 中切换相同程序的不同版本","tag":"201808","desc":""},"relativePath":"201808/20180813 How To Switch Between Different Versions Of Commands In Linux.md","filePath":"[post].md"}'),h={name:"201808/20180813 How To Switch Between Different Versions Of Commands In Linux.md"};function c(u,t,g,k,P,b){const e=l("Link");return d(),r("div",null,[t[18]||(t[18]=i("h1",{id:"如何在-linux-中切换相同程序的不同版本",tabindex:"-1"},[s("如何在 Linux 中切换相同程序的不同版本 "),i("a",{class:"header-anchor",href:"#如何在-linux-中切换相同程序的不同版本","aria-label":"Permalink to “如何在 Linux 中切换相同程序的不同版本”"},"​")],-1)),t[19]||(t[19]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/08/alt-tool-720x340.png",alt:""})],-1)),i("p",null,[t[1]||(t[1]=s("几天前，我们曾经讨论",-1)),a(e,{href:"https://www.ostechnix.com/how-to-switch-between-multiple-php-versions-in-ubuntu/"},{default:n(()=>[...t[0]||(t[0]=[s("如何在不同的 PHP 版本之间进行切换",-1)])]),_:1}),t[2]||(t[2]=p("。在那篇文章中，我们使用 <code>update-alternatives</code> 命令实现从一个 PHP 版本切换到另一个 PHP 版本。也就是说，<code>update-alternatives</code> 命令可以将<ruby>系统范围<rt>system wide</rt></ruby>默认使用的 PHP 版本设置为我们希望的版本。通俗的来说，你可以通过 <code>update-alternatives</code> 命令从系统范围设置程序的版本。如果你希望可以在不同目录动态设置不同的程序版本，该如何完成呢？在这种情况下，<code>alt</code> 工具可以大显身手。<code>alt</code> 是一个命令行工具，可以让你在类 Unix 系统中切换相同程序的不同版本。该工具简单易用，是 Rust 语言编写的自由、开源软件。",13))]),t[20]||(t[20]=p(`<h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>安装 <code>alt</code> 工具十分简单。</p><p>运行如下命令，即可在 Linux 主机上安装 <code>alt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -sL https://github.com/dotboris/alt/raw/master/install.sh | bash -s</span></span></code></pre></div><p>下一步，将 <code>shims</code> 目录添加到你的 PATH 环境变量中，具体操作取决于你使用的 Shell。</p><p>对于 Bash：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;export PATH=&quot;$HOME/.local/alt/shims:$PATH&quot;&#39; &gt;&gt; ~/.bashrc</span></span>
<span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>对于 Zsh：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;export PATH=&quot;$HOME/.local/alt/shims:$PATH&quot;&#39; &gt;&gt; ~/.zshrc</span></span>
<span class="line"><span>$ source ~/.zshrc</span></span></code></pre></div><p>对于 Fish：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;set -x PATH &quot;$HOME/.local/alt/shims&quot; $PATH&#39; &gt;&gt; ~/.config/fish/config.fish</span></span></code></pre></div><p>现在 <code>alt</code> 已经安装完毕！</p><h3 id="使用-alt-工具在-linux-系统中切换相同程序的不同版本" tabindex="-1">使用 alt 工具在 Linux 系统中切换相同程序的不同版本 <a class="header-anchor" href="#使用-alt-工具在-linux-系统中切换相同程序的不同版本" aria-label="Permalink to “使用 alt 工具在 Linux 系统中切换相同程序的不同版本”">​</a></h3><p>如我之前所述，alt 只影响当前目录。换句话说，当你进行版本切换时，只在当前目录生效，而不是整个系统范围。</p><p>下面举例说明。我在我的 Ubuntu 系统中安装了两个版本的 PHP，分别为 PHP 5.6 和 PHP 7.2；另外，在 <code>myproject</code> 目录中包含一些 PHP 应用。</p><p>首先，通过命令查看系统范围默认的 PHP 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ php -v</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Find-PHP-version.png" alt="查找 PHP 版本"></p><p>如截图中所示，我系统中默认的 PHP 版本为 PHP 7.2。</p><p>然后，我将进入放置 PHP 应用的 <code>myproject</code> 目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd myproject</span></span></code></pre></div><p>使用如下命令扫描可用的 PHP 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alt scan php</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/alt-scan-php.png" alt="扫描 PHP 版本"></p><p>可见，我有两个 PHP 版本，即 PHP 5.6 和 PHP 7.2。按下 <code>&lt;空格&gt;</code> 键选中当前可用的版本。选中全部可用版本后，你可以看到图中所示的<ruby>叉号<rt>cross mark</rt></ruby>。使用上下方向键在版本间移动，点击回车即可保存变更。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Select-php-version.png" alt="选取 PHP 版本"></p><p>下面运行该命令并选取我们希望在 <code>myproject</code> 目录中使用的 PHP 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alt use php</span></span></code></pre></div><p>我希望使用 PHP5.6 版本，故我（使用方向键）选取该版本并点击回车键。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/set-php-version.png" alt="设置 PHP 版本"></p><p>现在，你可以在 <code>/home/sk/myproject</code> 目录下使用 PHP 5.6 版本啦。</p><p>让我们检查一下，在 <code>myproject</code> 目录下是否默认使用 PHP 5.6 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ php -v</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Check-PHP-version.png" alt="检查 PHP 版本"></p><p>只要你不设置成其它版本，（在该目录下）将一直使用 PHP 5.6 版本。清楚了吗？很好！请注意，我们仅在这个目录下使用 PHP 5.6 版本。在系统范围内（LCTT 译注：当然是没单独设置过其它版本的目录下），PHP 7.2 仍是默认的版本。让我们检验一下，请看下图。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Check-PHP-version-1.png" alt="比对 PHP 版本"></p><p>从上面的截图中可以看出，我有两个版本的 PHP：在 <code>myproject</code> 目录下，使用的版本为 PHP 5.6；在 <code>myproject</code> 外的其它目录，使用的版本为 PHP 7.2。</p><p>同理，你可以为每个目录设置你希望的程序版本。我这里使用 PHP 仅用于说明操作，但方法适用于任何你打算使用的软件，例如 NodeJS 等。</p><p>下面是 NodeJS 的示例视频。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Alt-NodeJS-demo.gif" alt=""></p><p>如果你希望在不同软件包版本下测试你的应用，那么 <code>alt</code> 是你不错的选择。</p><p>本次分享到此结束。后续还有更多内容，敬请期待！</p><p>干杯！</p><hr>`,47)),i("p",null,[t[4]||(t[4]=s("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-switch-between-different-versions-of-commands-in-linux/"},{default:n(()=>[...t[3]||(t[3]=[s("https://www.ostechnix.com/how-to-switch-between-different-versions-of-commands-in-linux/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=s("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...t[5]||(t[5]=[s("SK",-1)])]),_:1}),t[10]||(t[10]=s(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[6]||(t[6]=[s("lujun9972",-1)])]),_:1}),t[11]||(t[11]=s(" 译者：",-1)),a(e,{href:"https://github.com/pinewall"},{default:n(()=>[...t[7]||(t[7]=[s("pinewall",-1)])]),_:1}),t[12]||(t[12]=s(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[s("Linux中国",-1)])]),_:1}),t[17]||(t[17]=s(" 荣誉推出",-1))])])}const x=o(h,[["render",c]]);export{w as __pageData,x as default};
